// SPDX-License-Identifier: BUSL-1.1
// Copyright (c) 2025-2026 Predictable Reality, Inc.
// Author: Carlos Revelo (Predictable Reality, Inc.)
pragma solidity 0.8.28;

import {Side, TickLevel, TickList, TickNode} from "../interfaces/Types.sol";

/**
 * @title LibOrderBookStorage
 * @notice Order book domain storage: tick levels, top of book, active tick list, tick nodes.
 * Read-only accessors here; writes (enqueue, dequeue, recordFill, top/active updates) in LibOrderBookAggregate.
 */
library LibOrderBookStorage {
    bytes32 constant STORAGE_POSITION = keccak256("oddmaki.storage.orderbook");

    struct Storage {
        // marketId => outcomeId => side => tick => TickLevel
        mapping(uint256 => mapping(uint256 => mapping(Side => mapping(uint256 => TickLevel)))) tickLevels;
        // marketId => outcomeId => side => bestTick
        mapping(uint256 => mapping(uint256 => mapping(Side => uint256))) topOfBook;
        // marketId => outcomeId => side => TickList
        mapping(uint256 => mapping(uint256 => mapping(Side => TickList))) activeTicks;
        // marketId => outcomeId => side => tick => TickNode
        mapping(uint256 => mapping(uint256 => mapping(Side => mapping(uint256 => TickNode)))) tickNodes;
    }

    function getStorage() internal pure returns (Storage storage s) {
        bytes32 position = STORAGE_POSITION;
        assembly {
            s.slot := position
        }
    }

    // -------------------------------------------------------------------------
    // Read-only accessors
    // -------------------------------------------------------------------------

    function getTickLevel(uint256 marketId, uint256 outcomeId, Side side, uint256 tick)
        internal
        view
        returns (TickLevel storage)
    {
        return getStorage().tickLevels[marketId][outcomeId][side][tick];
    }

    function getTopOfBook(uint256 marketId, uint256 outcomeId, Side side) internal view returns (uint256) {
        return getStorage().topOfBook[marketId][outcomeId][side];
    }

    function getActiveTickList(uint256 marketId, uint256 outcomeId, Side side)
        internal
        view
        returns (TickList storage)
    {
        return getStorage().activeTicks[marketId][outcomeId][side];
    }

    function getTickNode(uint256 marketId, uint256 outcomeId, Side side, uint256 tick)
        internal
        view
        returns (TickNode storage)
    {
        return getStorage().tickNodes[marketId][outcomeId][side][tick];
    }

    /// @notice Next best tick after emptyTick (O(1) via linked list). Returns 0 if none.
    function findNextBestTick(uint256 marketId, uint256 outcomeId, Side side, uint256 emptyTick)
        internal
        view
        returns (uint256)
    {
        return getTickNode(marketId, outcomeId, side, emptyTick).nextTick;
    }
}

src/aggregates/LibOrderAggregate.sol.content:
// SPDX-License-Identifier: BUSL-1.1
// Copyright (c) 2025-2026 Predictable Reality, Inc.
// Author: Carlos Revelo (Predictable Reality, Inc.)
pragma solidity 0.8.28;

import {LibOrderStorage} from "../storage/LibOrderStorage.sol";
import {Order, Side} from "../interfaces/Types.sol";

/**
 * @title LibOrderAggregate
 * @notice Order domain writes. All order mutations go through here; no external orderId for creation.
 * - createOrder: allocates id internally, validates, stores, returns Order (single creation path).
 * - reduceOrderQty: partial fills (clearing).
 * - updateOrderQueuePointers: order book enqueue/dequeue (next/prev links).
 * - deleteOrder: remove order (cancel, expire, or fully filled).
 * Read-only access via LibOrderStorage.
 */
library LibOrderAggregate {
    event OrderCreated(uint256 indexed orderId, address indexed owner, uint256 marketId);
    event OrderDeleted(uint256 indexed orderId);

    // -------------------------------------------------------------------------
    // Creation (single path; orderId is always allocated inside)
    // -------------------------------------------------------------------------

    /// @notice Create a new order. Allocates orderId internally; caller never passes orderId.
    /// @return newOrder The created order (includes orderId as newOrder.id).
    function createOrder(
        address owner,
        uint256 qty,
        uint256 tick,
        Side side,
        uint256 outcomeId,
        uint256 marketId,
        uint256 expiry,
        uint256 tickSize
    ) internal returns (Order memory newOrder) {
        _validateOrderParams(outcomeId, tick, qty, expiry, tickSize);

        uint256 orderId = _allocateOrderId();

        newOrder = Order({
            id: orderId,
            owner: owner,
            qty: qty,
            originalQty: qty,
            tick: tick,
            side: side,
            outcomeId: outcomeId,
            marketId: marketId,
            expiry: expiry,
            salt: uint256(keccak256(abi.encodePacked(owner, block.timestamp, orderId))),
            nextOrderId: 0,
            prevOrderId: 0
        });

        LibOrderStorage.getStorage().orders[orderId] = newOrder;

        emit OrderCreated(orderId, owner, marketId);

        return newOrder;
    }

    /// @notice Reduce remaining qty (e.g. after a fill). Caller must dequeue/delete when qty becomes 0.
    /// @return newQty Remaining qty after reduction.
    function reduceOrderQty(uint256 orderId, uint256 amount) internal returns (uint256 newQty) {
        Order storage order = LibOrderStorage.getOrder(orderId);
        require(order.id != 0, "Order not found");
        require(order.qty >= amount, "Insufficient order qty");
        order.qty -= amount;
        return order.qty;
    }

    /// @notice Set only the next pointer for an order (FIFO forward link).
    function setNextOrderId(uint256 orderId, uint256 nextId) internal {
        Order storage order = LibOrderStorage.getOrder(orderId);
        require(order.id != 0, "Order not found");
        order.nextOrderId = nextId;
    }

    /// @notice Set only the prev pointer for an order (FIFO backward link).
    function setPrevOrderId(uint256 orderId, uint256 prevId) internal {
        Order storage order = LibOrderStorage.getOrder(orderId);
        require(order.id != 0, "Order not found");
        order.prevOrderId = prevId;
    }

    /// @notice Remove order from storage (cancel, expire, or fully filled). Emits OrderDeleted.
    function deleteOrder(uint256 orderId) internal {
        require(LibOrderStorage.orderExists(orderId), "Order not found");
        delete LibOrderStorage.getStorage().orders[orderId];
        emit OrderDeleted(orderId);
    }

    // -------------------------------------------------------------------------
    // Internal helpers
    // -------------------------------------------------------------------------

    function _allocateOrderId() private returns (uint256 orderId) {
        LibOrderStorage.Storage storage s = LibOrderStorage.getStorage();
        orderId = s.nextOrderId;
        if (orderId == 0) {
            orderId = 1;
            s.nextOrderId = 2;
        } else {
            require(orderId != type(uint256).max, "OrderId overflow");
            s.nextOrderId = orderId + 1;
        }
        return orderId;
    }

    function _validateOrderParams(
        uint256 outcomeId,
        uint256 tick,
        uint256 qty,
        uint256 expiry,
        uint256 tickSize
    ) private view {
        if (outcomeId > 1) revert InvalidOutcome();
        if (qty == 0) revert InvalidQuantity();

        uint256 maxTick = 1e18 / tickSize;
        if (tick == 0 || tick > maxTick) revert InvalidTick();

        if (expiry != 0 && expiry <= block.timestamp) revert OrderExpired();

        // M-6/L-1: Prevent dust orders that round to zero collateral value.
        // tick * qty * tickSize / 1e18 must be >= 1 (at least 1 unit of collateral).
        if (tick * qty * tickSize < 1e18) revert OrderTooSmall();
    }

    // -------------------------------------------------------------------------
    // Errors
    // -------------------------------------------------------------------------

    error InvalidOutcome();
    error InvalidQuantity();
    error InvalidTick();
    error OrderExpired();
    error OrderTooSmall();
}

src/aggregates/LibOrderBookAggregate.sol.content:
// SPDX-License-Identifier: BUSL-1.1
// Copyright (c) 2025-2026 Predictable Reality, Inc.
// Author: Carlos Revelo (Predictable Reality, Inc.)
pragma solidity 0.8.28;

import {LibOrderBookStorage} from "../storage/LibOrderBookStorage.sol";
import {Side, TickLevel, TickList, TickNode} from "../interfaces/Types.sol";

/**
 * @title LibOrderBookAggregate
 * @notice Own-storage-only mutations for the OrderBook domain (LibOrderBookStorage).
 *         Manages tick levels, active tick lists, and top-of-book tracking.
 *         Cross-domain coordination (order pointer linking) lives in LibOrderBookService.
 */
library LibOrderBookAggregate {
    event TopOfBookChanged(uint256 indexed marketId, uint256 indexed outcomeId, Side side, uint256 bestTick);

    // -------------------------------------------------------------------------
    // Public write API
    // -------------------------------------------------------------------------

    /// @notice Add an order to its tick level. Returns old tail so caller can link FIFO pointers.
    /// @return oldTailOrderId Previous tail order ID (0 if level was empty).
    function addOrderToLevel(
        uint256 marketId,
        uint256 outcomeId,
        Side side,
        uint256 tick,
        uint256 orderId,
        uint256 orderQty
    ) internal returns (uint256 oldTailOrderId) {
        TickLevel storage level = LibOrderBookStorage.getTickLevel(marketId, outcomeId, side, tick);

        if (level.depth == 0) {
            _addActiveTickToList(marketId, outcomeId, side, tick);
        }

        oldTailOrderId = level.tailOrderId;

        if (oldTailOrderId == 0) {
            level.headOrderId = orderId;
        }
        level.tailOrderId = orderId;

        level.depth++;
        level.totalQty += orderQty;

        _updateTopOfBook(marketId, outcomeId, side, tick);
    }

    /// @notice Remove an order from its tick level. Caller provides pointer info read from Order storage.
    function removeOrderFromLevel(
        uint256 marketId,
        uint256 outcomeId,
        Side side,
        uint256 tick,
        uint256, /* orderId */
        uint256 orderQty,
        uint256 prevOrderId,
        uint256 nextOrderId
    ) internal {
        TickLevel storage level = LibOrderBookStorage.getTickLevel(marketId, outcomeId, side, tick);

        if (prevOrderId == 0) {
            level.headOrderId = nextOrderId;
        }

        if (nextOrderId == 0) {
            level.tailOrderId = prevOrderId;
        }

        level.depth--;
        level.totalQty -= orderQty;

        if (level.depth == 0) {
            _updateTopOfBookAfterRemoval(marketId, outcomeId, side, tick);
            _removeActiveTickFromList(marketId, outcomeId, side, tick);
        }
    }

    /// @notice Decrease level totalQty after a fill (partial or full). Does not dequeue.
    function recordFillOnBook(uint256 marketId, uint256 outcomeId, Side side, uint256 tick, uint256 filledQty)
        internal
    {
        TickLevel storage level = LibOrderBookStorage.getTickLevel(marketId, outcomeId, side, tick);
        level.totalQty -= filledQty;
    }

    // -------------------------------------------------------------------------
    // Top of book
    // -------------------------------------------------------------------------

    function _updateTopOfBook(uint256 marketId, uint256 outcomeId, Side side, uint256 tick) private {
        uint256 currentBest = LibOrderBookStorage.getTopOfBook(marketId, outcomeId, side);
        bool shouldUpdate = false;

        if (currentBest == 0) {
            shouldUpdate = true;
        } else if (side == Side.BUY && tick > currentBest) {
            shouldUpdate = true;
        } else if (side == Side.SELL && tick < currentBest) {
            shouldUpdate = true;
        }

        if (shouldUpdate) {
            LibOrderBookStorage.getStorage().topOfBook[marketId][outcomeId][side] = tick;
            emit TopOfBookChanged(marketId, outcomeId, side, tick);
        }
    }

    function _updateTopOfBookAfterRemoval(uint256 marketId, uint256 outcomeId, Side side, uint256 removedTick)
        private
    {
        uint256 currentBest = LibOrderBookStorage.getTopOfBook(marketId, outcomeId, side);

        if (currentBest == removedTick) {
            uint256 newBest = LibOrderBookStorage.findNextBestTick(marketId, outcomeId, side, removedTick);
            LibOrderBookStorage.getStorage().topOfBook[marketId][outcomeId][side] = newBest;
            emit TopOfBookChanged(marketId, outcomeId, side, newBest);
        }
    }

    // -------------------------------------------------------------------------
    // Active tick list (sorted: BUY = highest first, SELL = lowest first)
    // -------------------------------------------------------------------------

    function _addActiveTickToList(uint256 marketId, uint256 outcomeId, Side side, uint256 tick) private {
        TickList storage list = LibOrderBookStorage.getActiveTickList(marketId, outcomeId, side);
        TickNode storage node = LibOrderBookStorage.getTickNode(marketId, outcomeId, side, tick);

        if (node.active) return;

        node.active = true;

        if (list.head == 0) {
            list.head = tick;
            list.tail = tick;
            return;
        }

        if (side == Side.BUY) {
            if (tick > list.head) {
                node.nextTick = list.head;
                LibOrderBookStorage.getTickNode(marketId, outcomeId, side, list.head).prevTick = tick;
                list.head = tick;
                return;
            }
            if (tick < list.tail) {
                node.prevTick = list.tail;
                LibOrderBookStorage.getTickNode(marketId, outcomeId, side, list.tail).nextTick = tick;
                list.tail = tick;
                return;
            }
            uint256 current = list.head;
            while (current != 0) {
                uint256 next = LibOrderBookStorage.getTickNode(marketId, outcomeId, side, current).nextTick;
                if (next == 0 || tick > next) {
                    node.prevTick = current;
                    node.nextTick = next;
                    LibOrderBookStorage.getTickNode(marketId, outcomeId, side, current).nextTick = tick;
                    if (next != 0) {
                        LibOrderBookStorage.getTickNode(marketId, outcomeId, side, next).prevTick = tick;
                    } else {
                        list.tail = tick;
                    }
                    break;
                }
                current = next;
            }
        } else {
            if (tick < list.head) {
                node.nextTick = list.head;
                LibOrderBookStorage.getTickNode(marketId, outcomeId, side, list.head).prevTick = tick;
                list.head = tick;
                return;
            }
            if (tick > list.tail) {
                node.prevTick = list.tail;
                LibOrderBookStorage.getTickNode(marketId, outcomeId, side, list.tail).nextTick = tick;
                list.tail = tick;
                return;
            }
            uint256 current = list.head;
            while (current != 0) {
                uint256 next = LibOrderBookStorage.getTickNode(marketId, outcomeId, side, current).nextTick;
                if (next == 0 || tick < next) {
                    node.prevTick = current;
                    node.nextTick = next;
                    LibOrderBookStorage.getTickNode(marketId, outcomeId, side, current).nextTick = tick;
                    if (next != 0) {
                        LibOrderBookStorage.getTickNode(marketId, outcomeId, side, next).prevTick = tick;
                    } else {
                        list.tail = tick;
                    }
                    break;
                }
                current = next;
            }
        }
    }

    function _removeActiveTickFromList(uint256 marketId, uint256 outcomeId, Side side, uint256 tick) private {
        TickList storage list = LibOrderBookStorage.getActiveTickList(marketId, outcomeId, side);
        TickNode storage node = LibOrderBookStorage.getTickNode(marketId, outcomeId, side, tick);

        if (!node.active) return;

        if (node.prevTick != 0) {
            LibOrderBookStorage.getTickNode(marketId, outcomeId, side, node.prevTick).nextTick = node.nextTick;
        } else {
            list.head = node.nextTick;
        }

        if (node.nextTick != 0) {
            LibOrderBookStorage.getTickNode(marketId, outcomeId, side, node.nextTick).prevTick = node.prevTick;
        } else {
            list.tail = node.prevTick;
        }

        delete LibOrderBookStorage.getStorage().tickNodes[marketId][outcomeId][side][tick];
    }
}

src/services/LibOrderBookService.sol.content:
// SPDX-License-Identifier: BUSL-1.1
// Copyright (c) 2025-2026 Predictable Reality, Inc.
// Author: Carlos Revelo (Predictable Reality, Inc.)
pragma solidity 0.8.28;

import {LibOrderBookAggregate} from "../aggregates/LibOrderBookAggregate.sol";
import {LibOrderAggregate} from "../aggregates/LibOrderAggregate.sol";
import {LibOrderStorage} from "../storage/LibOrderStorage.sol";
import {Order, Side} from "../interfaces/Types.sol";

/**
 * @title LibOrderBookService
 * @notice Cross-domain coordination for order book enqueue/dequeue.
 *         Reads Order data, delegates tick-level management to LibOrderBookAggregate,
 *         and links FIFO pointers via LibOrderAggregate.
 */
library LibOrderBookService {
    /// @notice Add an order to the book at its tick, linking FIFO pointers.
    function enqueueOrder(uint256 orderId) internal {
        Order storage order = LibOrderStorage.getOrder(orderId);
        require(order.id != 0, "Order not found");

        uint256 oldTailOrderId = LibOrderBookAggregate.addOrderToLevel(
            order.marketId, order.outcomeId, order.side, order.tick, orderId, order.qty
        );

        // Link FIFO pointers if level had existing orders
        if (oldTailOrderId != 0) {
            LibOrderAggregate.setNextOrderId(oldTailOrderId, orderId);
            LibOrderAggregate.setPrevOrderId(orderId, oldTailOrderId);
        }
    }

    /// @notice Remove an order from the book, re-linking neighbor pointers.
    function dequeueOrder(uint256 orderId) internal {
        Order storage order = LibOrderStorage.getOrder(orderId);
        require(order.id != 0, "Order not found");

        uint256 prevId = order.prevOrderId;
        uint256 nextId = order.nextOrderId;

        LibOrderBookAggregate.removeOrderFromLevel(
            order.marketId, order.outcomeId, order.side, order.tick,
            orderId, order.qty, prevId, nextId
        );

        // Re-link neighbor pointers
        if (prevId != 0) {
            LibOrderAggregate.setNextOrderId(prevId, nextId);
        }
        if (nextId != 0) {
            LibOrderAggregate.setPrevOrderId(nextId, prevId);
        }
    }
}

