// SPDX-License-Identifier: BUSL-1.1
// Copyright (c) 2025-2026 Predictable Reality, Inc.
// Author: Carlos Revelo (Predictable Reality, Inc.)
pragma solidity 0.8.28;

import {LibOrderStorage} from "../storage/LibOrderStorage.sol";
import {LibOrderBookService} from "./LibOrderBookService.sol";
import {LibMarketTradingStorage} from "../storage/LibMarketTradingStorage.sol";
import {LibVaultCollateralService} from "./LibVaultCollateralService.sol";
import {LibVaultOutcomeTokenService} from "./LibVaultOutcomeTokenService.sol";
import {Order, Side, MarketTradingData} from "../interfaces/Types.sol";

/**
 * @title LibOrderExpiryService
 * @notice Order expiry: batch cleanup (expireOrders) and inline cleanup during matching (expireOrderInline).
 *         Full collateral / outcome-token refund to the order owner; no penalty.
 */
library LibOrderExpiryService {
    uint256 constant MAX_EXPIRE_BATCH = 100;

    error BatchTooLarge();

    event OrderExpired(uint256 indexed orderId, address indexed owner, uint256 qty);

    /**
     * @notice Expire a batch of orders for `marketId`.
     *         Orders that are not expired, belong to a different market, or are already
     *         removed are silently skipped.
     * @param marketId  Market the orders belong to (used for validation + market data lookup).
     * @param orderIds  Caller-supplied list of order IDs to attempt to expire.
     * @return expiredCount Number of orders actually expired and refunded.
     */
    function expireOrders(uint256 marketId, uint256[] calldata orderIds)
        internal
        returns (uint256 expiredCount)
    {
        if (orderIds.length > MAX_EXPIRE_BATCH) revert BatchTooLarge();

        LibOrderStorage.Storage storage os = LibOrderStorage.getStorage();

        for (uint256 i = 0; i < orderIds.length; i++) {
            uint256 orderId = orderIds[i];
            Order storage order = os.orders[orderId];

            // Skip: not found, wrong market, already removed, or not yet expired
            if (order.id == 0) continue;
            if (order.marketId != marketId) continue;
            if (order.qty == 0) continue;
            if (order.expiry == 0 || order.expiry > block.timestamp) continue;

            // Cache fields we need after deletion
            address owner = order.owner;
            uint256 qty = order.qty;
            Side side = order.side;
            uint256 tick = order.tick;
            uint256 outcomeId = order.outcomeId;

            // Load market data (collateralToken, tickSize, positionIds)
            MarketTradingData memory md = LibMarketTradingStorage.getMarketTradingData(marketId);

            // Refund locked assets to owner
            if (side == Side.BUY) {
                uint256 collateralLocked = (qty * tick * md.tickSize) / 1e18;
                LibVaultCollateralService.withdrawCollateral(address(md.collateralToken), owner, collateralLocked);
            } else {
                LibVaultOutcomeTokenService.withdrawOutcomeTokens(md.positionIds[outcomeId], owner, qty);
            }

            // Remove from order book (reads order storage — must happen before delete)
            LibOrderBookService.dequeueOrder(orderId);

            // Delete order record
            delete os.orders[orderId];

            emit OrderExpired(orderId, owner, qty);
            expiredCount++;
        }
    }

    /**
     * @notice Expire a single order inline during matching.
     *         Called when the FIFO head is found to be past its expiry before a fill is attempted.
     *         Full refund; no penalty. Returns true if the order was expired and removed.
     * @param orderId  Order to check and potentially expire.
     * @param md       Trading data for the order's market (collateralToken, tickSize, positionIds).
     */
    function expireOrderInline(uint256 orderId, MarketTradingData storage md)
        internal
        returns (bool wasExpired)
    {
        Order storage order = LibOrderStorage.getStorage().orders[orderId];

        if (order.id == 0) return false;
        if (order.expiry == 0 || order.expiry > block.timestamp) return false;

        address owner = order.owner;
        uint256 qty = order.qty;
        Side side = order.side;
        uint256 tick = order.tick;
        uint256 outcomeId = order.outcomeId;

        if (side == Side.BUY) {
            uint256 collateralLocked = (qty * tick * md.tickSize) / 1e18;
            LibVaultCollateralService.withdrawCollateral(address(md.collateralToken), owner, collateralLocked);
        } else {
            LibVaultOutcomeTokenService.withdrawOutcomeTokens(md.positionIds[outcomeId], owner, qty);
        }

        LibOrderBookService.dequeueOrder(orderId);
        delete LibOrderStorage.getStorage().orders[orderId];

        emit OrderExpired(orderId, owner, qty);
        return true;
    }
}

src/services/LibFeeCalculatorService.sol.content:
// SPDX-License-Identifier: BUSL-1.1
// Copyright (c) 2025-2026 Predictable Reality, Inc.
// Author: Carlos Revelo (Predictable Reality, Inc.)
pragma solidity 0.8.28;

import {MarketFees, FeeBreakdown, MarketRegistryData} from "../interfaces/Types.sol";
import {LibMarketRegistryStorage} from "../storage/LibMarketRegistryStorage.sol";

/**
 * @title LibFeeCalculatorService
 * @notice Fee config reader (composed view) + pure fee math.
 *
 * Fee Model:
 * - Protocol: 0-200 bps (configurable, snapshotted per market) -> protocol treasury
 * - Venue: 1-200 bps (configurable, snapshotted per market) -> split between venue net and creator
 * - Operator: 10 bps (fixed) -> msg.sender who called matchOrders
 * - Maker pays 0%. Taker bears all fees.
 *
 * Rounding: floor each component, remainder goes to protocol during distribution.
 */
library LibFeeCalculatorService {
    uint256 constant BPS_DENOMINATOR = 10_000;
    uint256 constant OPERATOR_FEE_BPS = 10;

    // =========================================================================
    // FEE CONFIG READER (composed view across multiple storage namespaces)
    // =========================================================================

    /**
     * @notice Compose MarketFees from the market registry's fee snapshot. Rates AND recipients
     *         are read from the per-market snapshot taken at creation — mutations to venue.feeRecipient
     *         or protocolTreasury after the market is live never redirect fees that resting makers
     *         priced in at placement (H-01 fix).
     *         Returns all-zero struct if protocolFeeRecipient == address(0) (fees disabled at creation).
     */
    function getMarketFees(uint256 marketId) internal view returns (MarketFees memory fees) {
        MarketRegistryData storage registry = LibMarketRegistryStorage.getMarketRegistryData(marketId);

        // If no protocol treasury was snapshotted, the market was created with fees disabled.
        if (registry.protocolFeeRecipient == address(0)) {
            return fees;
        }

        fees.protocolFeeBps = registry.protocolFeeBps;
        fees.venueFeeBps = registry.venueFeeBps;
        fees.creatorFeeBps = registry.creatorFeeBps;
        fees.operatorFeeBps = OPERATOR_FEE_BPS;
        fees.protocolTreasury = registry.protocolFeeRecipient;
        fees.venueTreasury = registry.venueFeeRecipient;
        fees.marketCreator = registry.creator;
    }

    // =========================================================================
    // FEE MATH (pure)
    // =========================================================================

    /**
     * @notice Calculate fee breakdown for a fill.
     *         Each component is floored; remainder tracked separately.
     */
    function calculateFees(uint256 tradeVolume, MarketFees memory fees)
        internal
        pure
        returns (FeeBreakdown memory breakdown)
    {
        breakdown.protocolFee = (tradeVolume * fees.protocolFeeBps) / BPS_DENOMINATOR;
        breakdown.creatorFee = (tradeVolume * fees.creatorFeeBps) / BPS_DENOMINATOR;
        breakdown.venueNetFee = (tradeVolume * (fees.venueFeeBps - fees.creatorFeeBps)) / BPS_DENOMINATOR;
        breakdown.operatorFee = (tradeVolume * fees.operatorFeeBps) / BPS_DENOMINATOR;

        breakdown.totalFee =
            breakdown.protocolFee + breakdown.venueNetFee + breakdown.creatorFee + breakdown.operatorFee;

        // Remainder from rounding dust -> goes to protocol during distribution
        uint256 expectedTotal = (tradeVolume * getTotalFeeBps(fees)) / BPS_DENOMINATOR;
        if (expectedTotal > breakdown.totalFee) {
            breakdown.remainder = expectedTotal - breakdown.totalFee;
        }
    }

    /**
     * @notice Total fee in basis points: protocol + venue + operator.
     *         Note: creatorFeeBps is a sub-split of venueFeeBps, not additive.
     */
    function getTotalFeeBps(MarketFees memory fees) internal pure returns (uint256) {
        return fees.protocolFeeBps + fees.venueFeeBps + fees.operatorFeeBps;
    }

    // =========================================================================
    // FEASIBILITY CHECKS (for Mint/Merge matching)
    // =========================================================================

    /**
     * @notice Check if Mint-to-Fill is feasible accounting for fees.
     *         (yesBid + noBid) >= fullPrice * (1 + totalFeeBps / 10000)
     */
    function checkMintFeasibility(
        uint256 yesBidTick,
        uint256 noBidTick,
        uint256 tickSize,
        MarketFees memory fees
    ) internal pure returns (bool) {
        uint256 fullPriceTicks = 1e18 / tickSize;
        uint256 totalFeeBps = getTotalFeeBps(fees);
        uint256 minRequiredTicks = (fullPriceTicks * (BPS_DENOMINATOR + totalFeeBps) + BPS_DENOMINATOR - 1) / BPS_DENOMINATOR;
        return (yesBidTick + noBidTick) >= minRequiredTicks;
    }

    /**
     * @notice Check if Merge-to-Fill is feasible accounting for fees.
     *         (yesAsk + noAsk) <= fullPrice * (1 - totalFeeBps / 10000)
     */
    function checkMergeFeasibility(
        uint256 yesAskTick,
        uint256 noAskTick,
        uint256 tickSize,
        MarketFees memory fees
    ) internal pure returns (bool) {
        uint256 fullPriceTicks = 1e18 / tickSize;
        uint256 totalFeeBps = getTotalFeeBps(fees);
        uint256 maxAllowedTicks = (fullPriceTicks * (BPS_DENOMINATOR - totalFeeBps)) / BPS_DENOMINATOR;
        return (yesAskTick + noAskTick) <= maxAllowedTicks;
    }

    // =========================================================================
    // SNAPSHOT HELPERS
    // =========================================================================

    /**
     * @notice Total fee BPS from market snapshot (protocol + venue + operator).
     */
    function getSnapshotedTotalFeeBps(uint256 marketId) internal view returns (uint256) {
        MarketRegistryData storage registry = LibMarketRegistryStorage.getMarketRegistryData(marketId);
        return registry.protocolFeeBps + registry.venueFeeBps + OPERATOR_FEE_BPS;
    }
}

src/services/LibFeeDistributionService.s.content:
// SPDX-License-Identifier: BUSL-1.1
// Copyright (c) 2025-2026 Predictable Reality, Inc.
// Author: Carlos Revelo (Predictable Reality, Inc.)
pragma solidity 0.8.28;

import {MarketFees, FeeBreakdown} from "../interfaces/Types.sol";
import {LibVaultCollateralService} from "./LibVaultCollateralService.sol";

/**
 * @title LibFeeDistributionService
 * @notice Distributes calculated fees to four recipients: protocol, venue, creator, operator.
 *         Protocol receives rounding remainder. Operator fee goes to msg.sender (preserved via delegatecall).
 */
library LibFeeDistributionService {
    event FeesDistributed(
        uint256 indexed marketId,
        uint256 indexed fillId,
        uint256 protocolFee,
        uint256 venueNetFee,
        uint256 creatorFee,
        uint256 operatorFee,
        uint256 totalFee
    );

    function distributeFees(
        address collateralToken,
        FeeBreakdown memory breakdown,
        MarketFees memory fees,
        uint256 marketId,
        uint256 fillId
    ) internal {
        // If totalFee is zero, nothing to distribute (fees disabled)
        if (breakdown.totalFee == 0 && breakdown.remainder == 0) return;

        // Protocol gets protocolFee + rounding remainder
        uint256 protocolAmount = breakdown.protocolFee + breakdown.remainder;
        if (protocolAmount > 0 && fees.protocolTreasury != address(0)) {
            LibVaultCollateralService.transferCollateral(collateralToken, fees.protocolTreasury, protocolAmount);
        }

        // Venue gets venueNetFee
        if (breakdown.venueNetFee > 0 && fees.venueTreasury != address(0)) {
            LibVaultCollateralService.transferCollateral(collateralToken, fees.venueTreasury, breakdown.venueNetFee);
        }

        // Creator gets creatorFee
        if (breakdown.creatorFee > 0 && fees.marketCreator != address(0)) {
            LibVaultCollateralService.transferCollateral(collateralToken, fees.marketCreator, breakdown.creatorFee);
        }

        // Operator gets operatorFee (msg.sender in Diamond delegatecall context)
        if (breakdown.operatorFee > 0) {
            LibVaultCollateralService.transferCollateral(collateralToken, msg.sender, breakdown.operatorFee);
        }

        emit FeesDistributed(
            marketId,
            fillId,
            protocolAmount,
            breakdown.venueNetFee,
            breakdown.creatorFee,
            breakdown.operatorFee,
            breakdown.totalFee + breakdown.remainder
        );
    }
}

